"use client";

import { BarChart3, BookOpenText, CircleGauge, ClipboardList, Database, FileCheck2, FlaskConical, GitCompare, Leaf, Moon, Play, Route, Scale, Server, Sparkles, Sun, TableProperties, Trophy, X, Zap } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { RunBenchmark } from "@/components/run-benchmark";
import { CrossSystem } from "@/components/cross-system";
import { Challenge } from "@/components/challenge";
import { OverviewHero } from "@/components/overview-hero";
import { EnergyFlow } from "@/components/energy-flow";
import { fetchLiveRecords } from "@/lib/api";
import { StagedQueryPlan as QueryPlan } from "@/components/staged-query-plan";
import { QualityMetrics } from "@/components/quality-metrics";
import { addLiveRecords, datasetDescription, datasetWorkload, median, modelLabel, primaryQuality, qualityFamily, qualitySummary, queryLabel, queryText, queryWorkload, records, type BenchmarkRecord } from "@/data/benchmarks";

type View = "Overview" | "Challenge" | "Cross-System" | "Run Benchmark" | "Query Lab" | "Model Compare" | "Compare Queries" | "Dataset Compare" | "Measurement Records";
type Pane = "plan" | "planning" | "results" | "evidence";
type Theme = "light" | "dark";
const views: Array<{ name: View; icon: typeof CircleGauge }> = [{ name: "Overview", icon: CircleGauge }, { name: "Challenge", icon: Trophy }, { name: "Cross-System", icon: Zap }, { name: "Run Benchmark", icon: Play }, { name: "Query Lab", icon: Route }, { name: "Model Compare", icon: Scale }, { name: "Compare Queries", icon: GitCompare }, { name: "Dataset Compare", icon: BarChart3 }, { name: "Measurement Records", icon: ClipboardList }];
const format = (value: number | null | undefined, digits = 2, unit = "") => typeof value === "number" && !Number.isNaN(value) ? `${value.toLocaleString(undefined, { maximumFractionDigits: digits })}${unit}` : "Not recorded";
let tokenDetails = "Not recorded";
let energyDetails = "Not recorded";
const compareQueriesStorageKey = "greenquery.compare-queries";
const themeStorageKey = "greenquery.theme";
const readCompareQueriesState = () => { if (typeof window === "undefined") return {}; try { return JSON.parse(window.localStorage.getItem(compareQueriesStorageKey) ?? "{}"); } catch { return {}; } };

function Metric({ label, value, detail, icon: Icon }: { label: string; value: string; detail: string; icon: typeof Zap }) { return <div className="metric"><div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div><Icon size={17} /></div>; }
function Stat({ label, value }: { label: string; value: string }) { return <div className="stat"><span>{label}</span><strong>{value}</strong>{label === "Tokens" && <small className="token-detail">{tokenDetails}</small>}{(label === "NVML energy" || label === "EcoLogits estimate") && <small className="energy-detail">{energyDetails}</small>}</div>; }
function Value({ value }: { value: string | number | null | undefined }) { return <>{value === null || value === undefined || value === "" ? "Not recorded" : value}</>; }
function ThemeToggle({ theme, onTheme }: { theme: Theme; onTheme: (value: Theme) => void }) { const next = theme === "light" ? "dark" : "light"; const Icon = theme === "light" ? Moon : Sun; return <button className="theme-toggle" type="button" onClick={() => onTheme(next)} aria-label={`Switch to ${next} mode`} title={`Switch to ${next} mode`}><Icon size={15} /><span>{next === "dark" ? "Dark mode" : "Light mode"}</span></button>; }

export default function Home() {
  // Bumped whenever live records from greenquery_server are merged into `records`.
  const [dataVersion, setDataVersion] = useState(0);
  const refreshLive = useCallback(() => {
    fetchLiveRecords().then((raw) => { if (addLiveRecords(raw)) setDataVersion((version) => version + 1); }).catch(() => undefined);
  }, []);
  useEffect(() => { refreshLive(); }, [refreshLive]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const datasets = useMemo(() => ["", ...[...new Set(records.map((record) => record.dataset))].sort()], [dataVersion]);
  const [view, setView] = useState<View>("Overview");
  // ?view=<name> opens a view directly (demo links, screenshots).
  useEffect(() => {
    const requested = new URLSearchParams(window.location.search).get("view")?.toLowerCase();
    const match = views.find((item) => item.name.toLowerCase() === requested);
    if (match) setView(match.name);
  }, []);
  const [dataset, setDataset] = useState("");
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const datasetRecords = useMemo(() => records.filter((record) => record.dataset === dataset), [dataset, dataVersion]);
  const queries = useMemo(() => [...new Set(datasetRecords.map((record) => record.query))].sort(), [datasetRecords]);
  const [query, setQuery] = useState("");
  const queryRecords = useMemo(() => datasetRecords.filter((record) => record.query === query), [datasetRecords, query]);
  const models = useMemo(() => [...new Set(queryRecords.map((record) => record.model))].sort(), [queryRecords]);
  const [model, setModel] = useState("");
  const modelRecords = useMemo(() => queryRecords.filter((record) => record.model === model), [queryRecords, model]);
  const runs = useMemo(() => modelRecords.map((record) => record.run).sort(), [modelRecords]);
  const [run, setRun] = useState("");
  const [compareMetric, setCompareMetric] = useState<QueryCompareMetric>("energy");
  const [compareQueries, setCompareQueries] = useState<string[]>([]);
  const [theme, setTheme] = useState<Theme>("light");
  const [themeReady, setThemeReady] = useState(false);
  useEffect(() => { const timer = window.setTimeout(() => { const stored = window.localStorage.getItem(themeStorageKey); if (stored === "dark" || stored === "light") setTheme(stored); setThemeReady(true); }, 0); return () => window.clearTimeout(timer); }, []);
  useEffect(() => { if (themeReady) window.localStorage.setItem(themeStorageKey, theme); }, [theme, themeReady]);
  const selected = modelRecords.find((record) => record.run === run) ?? modelRecords[0] ?? queryRecords[0] ?? ({ query: "" } as BenchmarkRecord);
  const [pane, setPane] = useState<Pane>("plan");
  const selectDataset = (value: string) => { const next = records.filter((record) => record.dataset === value); const nextQuery = [...new Set(next.map((record) => record.query))].sort()[0] ?? ""; const nextRecords = next.filter((record) => record.query === nextQuery); const nextModel = [...new Set(nextRecords.map((record) => record.model))].sort()[0] ?? ""; setDataset(value); setQuery(nextQuery); setModel(nextModel); setRun(nextRecords.find((record) => record.model === nextModel)?.run ?? ""); if (value === "") setCompareQueries([]); };
  const selectQuery = (value: string) => { const next = datasetRecords.filter((record) => record.query === value); const nextModel = [...new Set(next.map((record) => record.model))].sort()[0] ?? ""; setQuery(value); setModel(nextModel); setRun(next.find((record) => record.model === nextModel)?.run ?? ""); };
  const selectModel = (value: string) => { const next = queryRecords.filter((record) => record.model === value); setModel(value); setRun(next[0]?.run ?? ""); };
  const phaseRecords = records.filter((record) => record.planner_energy_wh !== null && record.execution_energy_wh !== null).length;
  return <main className="app-shell" data-theme={theme} suppressHydrationWarning><aside className="sidebar"><div className="brand"><div className="brand-mark"><Leaf size={21} /></div><div><strong>GreenQuery</strong><span>Research console</span></div></div><nav aria-label="Primary navigation">{views.map(({ name, icon: Icon }) => <button className={view === name ? "nav-item active" : "nav-item"} onClick={() => setView(name)} key={name}><Icon size={17} /><span>{name}</span></button>)}</nav><div className="sidebar-foot"><div className="evidence-dot" /><span>{records.length} records</span><small>{records.filter((record) => record.source === "live").length} live · rest archived</small></div></aside><section className="workspace"><header className="topbar"><div><span className="eyebrow">SUSTAINABLE QUERY RESEARCH</span><h1>{view === "Model Compare" && query ? queryLabel(query) : view}</h1></div><div className="topbar-actions"><ThemeToggle theme={theme} onTheme={setTheme} /><div className="top-meta"><span><Server size={14} /> Local + online bundles</span><span><FileCheck2 size={14} /> {phaseRecords}/{records.length} phase records</span></div></div></header>{view === "Challenge" && <Challenge onShowResults={() => setView("Cross-System")} />}{view === "Cross-System" && <CrossSystem />}{view === "Run Benchmark" && <RunBenchmark onRecords={refreshLive} onShowResults={() => setView("Cross-System")} />}{view === "Overview" && <Overview onOpen={() => setView("Query Lab")} onCompare={() => setView("Cross-System")} dataset={dataset} datasets={datasets} onDataset={selectDataset} />}{view === "Query Lab" && selected && <QueryLab dataset={dataset} query={query} model={model} run={run} datasets={datasets} queries={queries} models={models} runs={runs} selected={selected} cohort={modelRecords} pane={pane} onDataset={selectDataset} onQuery={selectQuery} onModel={selectModel} onRun={setRun} onPane={setPane} />}{view === "Model Compare" && <ModelCompare source={queryRecords} query={query} dataset={dataset} />}{view === "Compare Queries" && <CompareQueries dataset={dataset} model={model} onDataset={selectDataset} onModel={selectModel} metric={compareMetric} onMetric={setCompareMetric} selectedQueries={compareQueries} onSelectedQueries={setCompareQueries} />}{view === "Dataset Compare" && <DatasetCompare />}{view === "Measurement Records" && <MeasurementRecords source={records} dataset={dataset} onDataset={selectDataset} />}</section></main>;
}

function Overview({ onOpen, onCompare, dataset, datasets, onDataset }: { onOpen: () => void; onCompare: () => void; dataset: string; datasets: string[]; onDataset: (value: string) => void }) {
  const scopeRecords = dataset ? records.filter((record) => record.dataset === dataset) : records;
  const scopeDatasets = [...new Set(scopeRecords.map((record) => record.dataset))].sort();
  const local = scopeRecords.filter((record) => record.deployment === "Local DGX");
  const online = scopeRecords.filter((record) => record.deployment === "Online API");
  const measured = scopeRecords.filter((record) => record.energy_provenance === "NVML measurement");
  const estimated = scopeRecords.filter((record) => record.energy_provenance === "EcoLogits estimate");
  const queryPairs = [...new Set(scopeRecords.map((record) => `${record.dataset}:${record.query}`))];
  const scopeQueries = new Set(scopeRecords.map((record) => record.query)).size;
  const scopeModels = new Set(scopeRecords.map((record) => record.model)).size;
  const phaseCoverage = scopeRecords.length ? scopeRecords.filter((record) => record.planner_energy_wh !== null && record.execution_energy_wh !== null).length / scopeRecords.length : 0;
  const medianEnergy = local.length && estimated.length ? null : median(scopeRecords.map((record) => record.energy_wh));
  const coverageRows = scopeDatasets.map((item) => {
    const rows = scopeRecords.filter((record) => record.dataset === item);
    return {
      dataset: item,
      description: datasetDescription(item),
      workload: datasetWorkload(item),
      runs: rows.length,
      queries: new Set(rows.map((record) => record.query)).size,
      models: new Set(rows.map((record) => record.model)).size,
      runtime: median(rows.map((record) => record.runtime_seconds)),
      energy: median(rows.map((record) => record.energy_wh)),
      co2: median(rows.map((record) => record.co2_g)),
      phase: rows.filter((record) => record.planner_energy_wh !== null && record.execution_energy_wh !== null).length,
      plans: rows.filter((record) => record.physical_operators?.length).length,
      quality: rows.filter((record) => record.quality_metric !== "unavailable").length,
      sources: [...new Set(rows.map((record) => record.deployment))],
      families: [...new Set(rows.map(qualityFamily))],
    };
  });
  const scopeLabel = dataset ? `Dataset scope · ${dataset}` : "Archive scope · all datasets";
  const scopeDescription = dataset ? "Dataset-level medians across every recorded query, model, and run in this dataset." : "Archive-wide medians across every recorded query, model, and run.";
  return <div className="page-stack"><OverviewHero onCompare={onCompare} /><section className="overview-intro"><div><span className="eyebrow">BENCHMARK ARCHIVE</span><h2>Benchmark overview</h2><p>See dataset scope, recorded coverage, and median resource use before opening a query.</p></div><div className="overview-actions"><button className="primary-action" onClick={onOpen}><Play size={16} /> Open Query Lab</button></div></section><section className="overview-scope"><label><span>Dataset scope</span><select value={dataset} onChange={(event) => onDataset(event.target.value)}><option value="">All datasets</option>{datasets.filter(Boolean).map((item) => <option value={item} key={item}>{item}</option>)}</select></label><div><strong>{scopeLabel}</strong><small>{scopeDescription} Values on this page are medians unless explicitly labelled otherwise.</small></div></section><section className="metric-grid"><Metric label="Archived records" value={scopeRecords.length.toLocaleString()} detail={dataset ? `recorded executions in ${dataset}` : "recorded executions in archive"} icon={ClipboardList} /><Metric label="Queries" value={scopeQueries.toLocaleString()} detail={`${queryPairs.length} dataset-query pairs`} icon={Database} /><Metric label="Median total energy" value={medianEnergy === null && local.length && estimated.length ? "Mixed sources" : format(medianEnergy, 2, " Wh")} detail={local.length && estimated.length ? "NVML measurements and EcoLogits estimates cannot be pooled" : "median across recorded values"} icon={Zap} /><Metric label="Phase coverage" value={`${Math.round(phaseCoverage * 100)}%`} detail={`${scopeModels} model${scopeModels === 1 ? "" : "s"} · planner + execution`} icon={FlaskConical} /></section><section className="overview-grid"><section className="panel overview-panel"><div className="panel-heading"><div><span className="eyebrow">DEPLOYMENT SPLIT</span><h3>Where the runs came from</h3></div><span>{scopeLabel}</span></div><div className="overview-split"><div><strong>{local.length}</strong><span>Local DGX</span><small>measured local-model runs</small></div><div><strong>{online.length}</strong><span>Online API</span><small>remote-model runs</small></div></div></section><section className="panel overview-panel"><div className="panel-heading"><div><span className="eyebrow">MEASUREMENT PROVENANCE</span><h3>How resource values were obtained</h3></div><span>{scopeRecords.length} scoped runs</span></div><div className="provenance-list"><div><strong>{measured.length}</strong><span>NVML measurement</span></div><div><strong>{estimated.length}</strong><span>EcoLogits estimate</span></div><div><strong>{Math.round(phaseCoverage * 100)}%</strong><span>phase energy coverage</span></div></div></section></section><section className="panel overview-panel"><div className="panel-heading"><div><span className="eyebrow">DATA COVERAGE</span><h3>Available sources by dataset</h3></div><span>{scopeDatasets.length} dataset{scopeDatasets.length === 1 ? "" : "s"}</span></div><div className="coverage-list">{coverageRows.map((item) => <div key={item.dataset}><strong>{item.dataset}</strong><span>{item.runs} runs · {item.queries} queries · {item.models} models</span><small>Runtime {format(item.runtime, 2, " s")} · Energy {item.sources.length > 1 ? "mixed sources" : format(item.energy, 2, " Wh")} · CO2 {item.sources.length > 1 ? "mixed sources" : format(item.co2, 2, " g")} · {item.sources.join(" + ")}</small><small>Quality coverage: {item.quality}/{item.runs} runs · {item.families.join(" · ")}</small></div>)}</div></section><section className="panel overview-panel entry-panel"><div><span className="eyebrow">NEXT STEP</span><h3>Start with one query, then compare its models.</h3><p>Use Query Lab for a single recorded run and Model Compare for query-level medians across models.</p></div><button className="primary-action" onClick={onOpen}><Route size={15} /> Open a query</button></section></div>;
}

function QueryLab(props: { dataset: string; query: string; model: string; run: string; datasets: string[]; queries: string[]; models: string[]; runs: string[]; selected: BenchmarkRecord; cohort: BenchmarkRecord[]; pane: Pane; onDataset: (value: string) => void; onQuery: (value: string) => void; onModel: (value: string) => void; onRun: (value: string) => void; onPane: (value: Pane) => void; }) {
  const { selected } = props;
  const evidence = selected.planner_energy_wh != null && selected.execution_energy_wh != null;
  const number = (value: unknown) => typeof value === "number" ? value : null;
  const phaseTokens = (phase: "planner" | "execution") => (number(selected[`${phase}_input_tokens`]) ?? 0) + (number(selected[`${phase}_output_tokens`]) ?? 0);
  // eslint-disable-next-line react-hooks/globals
  tokenDetails = selected.query ? `Planner ${format(phaseTokens("planner"), 0)} · Execution ${format(phaseTokens("execution"), 0)}` : "Not recorded";
  // eslint-disable-next-line react-hooks/globals
  energyDetails = selected.query ? `Planner ${format(selected.planner_energy_wh, 3, " Wh")} · Execution ${format(selected.execution_energy_wh, 3, " Wh")}` : "Planner Not recorded · Execution Not recorded";
  const medians = { runtime: median(props.cohort.map((record) => record.runtime_seconds)), energy: median(props.cohort.map((record) => record.energy_wh)), co2: median(props.cohort.map((record) => record.co2_g)) };
  const quality = !selected.query ? "Not recorded" : selected.dataset === "RotoWire" ? "Unavailable: historical scorer" : qualitySummary(selected);
  const selectedScope = selected.query ? `Single recorded run · ${props.cohort.length} recorded runs available for this query and model` : "No query selected · choose a dataset to begin";
  return <div className="query-lab"><section className="source-bar"><label><span>Dataset</span><select value={props.dataset} onChange={(event) => props.onDataset(event.target.value)}><option value="">Select a dataset</option>{props.datasets.filter(Boolean).map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Load query</span><select value={props.query} onChange={(event) => props.onQuery(event.target.value)} disabled={!props.dataset}><option value="">Select a query</option>{props.queries.map((item) => <option value={item} key={item}>{queryLabel(item)}</option>)}</select></label><label><span>Model</span><select value={props.model} onChange={(event) => props.onModel(event.target.value)} disabled={!props.query}><option value="">Select a model</option>{props.models.map((item) => <option value={item} key={item}>{modelLabel(item)}</option>)}</select></label><label><span>Recorded run</span><select value={props.run} onChange={(event) => props.onRun(event.target.value)} disabled={!props.model}><option value="">Select a run</option>{props.runs.map((item) => <option value={item} key={item}>{item}</option>)}</select></label><button className="primary-action inspect" onClick={() => props.onPane("plan")}><Play size={15} /> Inspect benchmark</button></section><section className="query-editor"><div className="editor-gutter"><span>01</span><span>02</span><span>03</span><span>04</span></div><div><span className="editor-comment">-- {props.query ? queryLabel(props.query) : "Select a query"}</span><p>{props.query ? queryText(props.query) : "The query, model, run measurements, and recorded execution plan will appear after a dataset is selected."}</p><div className="query-tags"><span>{props.dataset || "Dataset not selected"}</span><span>{props.model ? modelLabel(props.model) : "Model not selected"}</span><span>{props.run || "Run not selected"}</span></div><div className="query-scope"><span>Analysis scope</span><strong>{selectedScope}</strong><small>{selected.query ? "Selected-run statistics are shown on the right; comparison values use the recorded cohort median." : "Fresh Query Lab state"}</small></div></div></section><section className="lab-grid"><aside className="mode-rail" aria-label="Query lab view"><Rail active={props.pane === "plan"} icon={Route} label="Plan" onClick={() => props.onPane("plan")} /><Rail active={props.pane === "planning"} icon={CircleGauge} label="Planning" onClick={() => props.onPane("planning")} /><Rail active={props.pane === "results"} icon={TableProperties} label="Results" onClick={() => props.onPane("results")} /><Rail active={props.pane === "evidence"} icon={BookOpenText} label="Evidence" onClick={() => props.onPane("evidence")} /></aside><section className="main-pane">{props.pane === "plan" && <><div className="pane-title"><div><span className="eyebrow">RECORDED EXECUTION</span><h3>Recorded Execution Plan</h3></div><span className="read-only"><CircleGauge size={14} /> Read-only trace</span></div><EnergyFlow record={selected} /><QueryPlan operators={selected.physical_operators} query={selected.query} executionPlan={selected.execution_plan} record={selected} /></>}{props.pane === "planning" && <PlanningUnavailable />}{props.pane === "results" && <Results record={selected} />}{props.pane === "evidence" && <Evidence record={selected} />}</section><aside className="stats-pane"><div className="pane-title"><div><span className="eyebrow">SELECTED RUN</span><h3>Measured query</h3></div></div><Stat label="Total runtime" value={format(selected.runtime_seconds, 2, " s")} /><Stat label={selected.deployment === "Online API" ? "EcoLogits estimate" : selected.deployment === "Local server" ? "Energy (not measured)" : "NVML energy"} value={format(selected.energy_wh, 3, " Wh")} /><Stat label="CO2 emissions" value={format(selected.co2_g, 3, " g")} /><Stat label="Tokens" value={format(number(selected.total_tokens), 0)} /><Stat label="Requests" value={`${format(number(selected.planner_requests), 0)} planning / ${format(number(selected.local_requests), 0)} execution`} /><Stat label="App cache" value={number(selected.cache_hits) === 0 ? "0 hits" : `${format(number(selected.cache_hits), 0)} hits`} /><Stat label="Quality" value={quality} /><div className={evidence ? "evidence-state recorded" : "evidence-state missing"}><span>{evidence ? "Phase energy recorded" : "Phase energy not recorded"}</span><small>{evidence ? `Planner ${format(selected.planner_energy_wh, 3, " Wh")} · Execution ${format(selected.execution_energy_wh, 3, " Wh")}` : "Phase-level runtime and energy were not recorded for this run; total-query measurements remain available."}</small></div><div className="phase-breakdown"><span>Phase token workload</span><small>Planner {format(phaseTokens("planner"), 0)} · Execution {format(phaseTokens("execution"), 0)}</small><strong>10-run medians: {format(medians.runtime, 2, " s")} · {format(medians.energy, 3, " Wh")} · {format(medians.co2, 3, " g")}</strong></div></aside></section><footer className="statusbar"><span><span className="evidence-dot" /> 10 archived repetitions</span><span>{selected.physical_operators?.length ?? 0} physical operators</span><span>{selected.quality_status} quality status</span></footer></div>;
}

function Rail({ active, icon: Icon, label, onClick }: { active: boolean; icon: typeof Route; label: string; onClick: () => void }) { return <button className={active ? "rail-button active" : "rail-button"} aria-label={label} title={label} onClick={onClick}><Icon size={19} /><span>{label}</span></button>; }
function PlanningUnavailable() { return <div className="planning-unavailable"><span className="eyebrow">PLANNING TRACE</span><h3>Planning trace unavailable</h3><p>This archive records final physical operators and query-level measurements, not discovery output, logical-plan reasoning, mapping prompts, intermediate observations, optimizer candidates, error budgets, or cascade routing.</p></div>; }
function Results({ record }: { record: BenchmarkRecord }) { return <div className="content-panel"><div className="pane-title"><div><span className="eyebrow">QUALITY AND OUTPUT</span><h3>Benchmark result</h3></div><span className="status-tag">{record.quality_status}</span></div><QualityMetrics record={record} /><div className="result-row"><span>Ground truth</span><strong><Value value={record.ground_truth} /></strong></div></div>; }
function Evidence({ record }: { record: BenchmarkRecord }) { const pairs = [["Energy source", String(record.energy_source ?? "")], ["Phase provenance", String(record.phase_energy_provenance ?? "")], ["Planner energy", format(record.planner_energy_wh, 3, " Wh")], ["Execution energy", format(record.execution_energy_wh, 3, " Wh")], ["Planner samples", format(Number(record.planner_nvml_sample_count), 0)], ["Execution samples", format(Number(record.execution_nvml_sample_count), 0)]]; return <div className="content-panel"><div className="pane-title"><div><span className="eyebrow">MEASUREMENT EVIDENCE</span><h3>Run provenance</h3></div></div><div className="evidence-list">{pairs.map(([label, value]) => <div key={label}><span>{label}</span><strong><Value value={value === "Not recorded" ? null : value} /></strong></div>)}</div></div>; }

type ModelChart = "quality" | "latency-energy" | "accuracy-energy" | "co2" | "pareto";
type ModelSummary = { model: string; deployment: string; rows: BenchmarkRecord[]; energy: number | null; co2: number | null; runtime: number | null; tokens: number | null; cost: number | null; quality: number | null; secondary: number | null; secondaryLabel: string | null };
const modelChartOptions: Array<{ value: ModelChart; label: string }> = [{ value: "quality", label: "Quality" }, { value: "latency-energy", label: "Latency vs energy" }, { value: "accuracy-energy", label: "Accuracy vs energy" }, { value: "co2", label: "CO2" }, { value: "pareto", label: "Pareto frontier" }];

function ModelPlot({ chart, rows, contract }: { chart: Exclude<ModelChart, "quality">; rows: ModelSummary[]; contract: NonNullable<ReturnType<typeof primaryQuality>> | null }) {
  const metricRows = rows.filter((row) => chart === "co2" ? row.co2 !== null : chart === "latency-energy" ? row.runtime !== null && row.energy !== null : row.energy !== null && row.quality !== null);
  const missingRows = rows.filter((row) => !metricRows.includes(row));
  if (!metricRows.length) return <section className="panel chart-panel model-plot-panel"><div className="chart-heading"><div><span className="eyebrow">MODEL PLOT</span><h3>{chart === "co2" ? "CO2 comparison" : chart === "latency-energy" ? "Latency vs energy" : chart === "pareto" ? "Pareto frontier" : "Accuracy vs energy"}</h3></div></div><p className="empty-state">No recorded values support this plot for the selected query and models.</p></section>;
  const width = 640;
  const height = Math.max(270, metricRows.length * 48 + 110);
  const left = 124;
  const right = 26;
  const top = 28;
  const bottom = 54;
  const plotWidth = width - left - right;
  const plotHeight = height - top - bottom;
  const ticks = [0, .25, .5, .75, 1];
  const values = chart === "co2" ? metricRows.map((row) => row.co2 as number) : chart === "latency-energy" ? metricRows.map((row) => row.runtime as number) : metricRows.map((row) => row.energy as number);
  const xMax = Math.max(...values, 1) * 1.12;
  const x = (value: number) => left + (value / xMax) * plotWidth;
  const range = (items: number[]) => { const min = Math.min(...items); const max = Math.max(...items); const pad = Math.max((max - min) * .14, max * .04, .02); return { min: Math.max(0, min - pad), max: max + pad }; };
  const yValues = chart === "latency-energy" ? metricRows.map((row) => row.energy as number) : metricRows.map((row) => row.quality as number);
  const yRange = range(yValues);
  const y = (value: number) => top + plotHeight - ((value - yRange.min) / (yRange.max - yRange.min || 1)) * plotHeight;
  const yTickValue = (tick: number) => yRange.min + tick * (yRange.max - yRange.min);
  const qualityScore = (row: ModelSummary) => contract?.direction === "lower is better" ? -(row.quality ?? 0) : row.quality ?? 0;
  const efficient = new Set(metricRows.filter((row) => row.quality !== null && row.energy !== null && metricRows.every((other) => other === row || other.energy === null || other.quality === null || !(other.energy <= row.energy! && qualityScore(other) >= qualityScore(row) && (other.energy < row.energy! || qualityScore(other) > qualityScore(row))))).map((row) => row.model));
  const xLabel = chart === "co2" ? "CO2 emissions (g)" : chart === "latency-energy" ? "Median runtime (s)" : "Median energy (Wh)";
  const yLabel = chart === "co2" ? "Models" : chart === "latency-energy" ? "Median energy (Wh)" : contract ? `${contract.label} (${contract.direction})` : "Recorded quality";
  const title = chart === "co2" ? "CO2 comparison" : chart === "latency-energy" ? "Latency vs energy" : chart === "pareto" ? "Pareto frontier" : "Accuracy vs energy";
  return <section className="panel chart-panel model-plot-panel"><div className="chart-heading"><div><span className="eyebrow">MODEL TRADE-OFFS</span><h3>{title}</h3></div><span>medians across recorded runs</span></div><svg className="model-plot" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${title} for ${rows.length} models`}>{ticks.map((tick) => <g key={tick}><line x1={left + tick * plotWidth} y1={top} x2={left + tick * plotWidth} y2={height - bottom} className="plot-grid" /><text x={left + tick * plotWidth} y={height - 32} textAnchor="middle" className="plot-tick">{format(xMax * tick, chart === "latency-energy" ? 0 : 2)}</text>{chart !== "co2" && <><line x1={left} y1={y(yTickValue(tick))} x2={width - right} y2={y(yTickValue(tick))} className="plot-grid" /><text x={left - 10} y={y(yTickValue(tick)) + 4} textAnchor="end" className="plot-tick">{format(yTickValue(tick), chart === "latency-energy" ? 2 : 2)}</text></>}</g>)}<line x1={left} y1={top} x2={left} y2={height - bottom} className="plot-axis" /><line x1={left} y1={height - bottom} x2={width - right} y2={height - bottom} className="plot-axis" />{chart === "co2" ? metricRows.map((row, index) => { const rowY = top + (plotHeight / Math.max(metricRows.length - 1, 1)) * index; return <g key={row.model}><text x={left - 10} y={rowY + 4} textAnchor="end" className="plot-label">{modelLabel(row.model)}</text><line x1={left} y1={rowY} x2={x(row.co2!)} y2={rowY} className="plot-stem" /><circle cx={x(row.co2!)} cy={rowY} r="6" className={`plot-point ${row.deployment === "Local DGX" ? "local" : "online"}`} /><title>{`${modelLabel(row.model)}: ${format(row.co2, 3, " g")}`}</title></g>; }) : metricRows.map((row) => { const xValue = chart === "latency-energy" ? row.runtime! : row.energy!; const yValue = chart === "latency-energy" ? row.energy! : row.quality!; const highlighted = chart === "pareto" && efficient.has(row.model); const pointClass = highlighted ? "plot-point efficient" : `plot-point ${row.deployment === "Local DGX" ? "local" : "online"}`; const pointX = x(xValue); const pointY = y(yValue); const labelRight = pointX < width - right - 110; return <g key={row.model}><circle cx={pointX} cy={pointY} r={highlighted ? 7 : 5} className={pointClass} /><text x={labelRight ? pointX + 9 : pointX - 9} y={pointY + 4} textAnchor={labelRight ? "start" : "end"} className="plot-label">{modelLabel(row.model)}</text><title>{`${modelLabel(row.model)}: ${format(xValue, 2)} on x-axis, ${format(yValue, 3)} on y-axis`}</title></g>; })}<text x={left + plotWidth / 2} y={height - 7} textAnchor="middle" className="plot-axis-title">{xLabel}</text><text x="16" y={top + plotHeight / 2} transform={`rotate(-90 16 ${top + plotHeight / 2})`} textAnchor="middle" className="plot-axis-title">{yLabel}</text></svg><div className="model-plot-legend"><span><i className="legend-dot local" /> Local DGX</span><span><i className="legend-dot online" /> Online API</span>{chart === "pareto" && <span><i className="legend-dot efficient" /> Pareto-efficient</span>}</div>{missingRows.length > 0 && <p className="plot-missing">Not plotted: {missingRows.map((row) => modelLabel(row.model)).join(", ")} · required metric not recorded.</p>}</section>;
}

function ModelCompare({ source, query, dataset }: { source: BenchmarkRecord[]; query: string; dataset: string }) {
  const contract = source[0] ? primaryQuality(source[0]) : null;
  const [chart, setChart] = useState<ModelChart>("quality");
  const allModels = [...new Set(source.map((record) => record.model))].sort();
  const [visibleModels, setVisibleModels] = useState(allModels);
  const summary: ModelSummary[] = allModels.map((model) => {
    const rows = source.filter((record) => record.model === model);
    const qualities = rows.map(primaryQuality).filter((item): item is NonNullable<typeof item> => item !== null);
    return { model, deployment: rows[0]?.deployment ?? "Unknown", rows, energy: median(rows.map((row) => row.energy_wh)), co2: median(rows.map((row) => row.co2_g)), runtime: median(rows.map((row) => row.runtime_seconds)), tokens: median(rows.map((row) => typeof row.total_tokens === "number" ? row.total_tokens : null)), cost: median(rows.map((row) => typeof row.api_cost_usd === "number" ? row.api_cost_usd : null)), quality: median(qualities.map((item) => item.value)), secondary: median(qualities.map((item) => item.secondary?.value)), secondaryLabel: qualities.find((item) => item.secondary)?.secondary?.label ?? null };
  });
  const shown = summary.filter((item) => visibleModels.includes(item.model));
  const lowEnergy = Math.min(...shown.map((item) => item.energy ?? Infinity));
  const qualityValues = shown.map((item) => item.quality).filter((value): value is number => value !== null);
  const minQuality = Math.min(...qualityValues, 0);
  const maxQuality = Math.max(...qualityValues, 1);
  const position = (value: number | null, min: number, max: number, reverse = false) => value === null ? 5 : 5 + (reverse ? (max - value) : (value - min)) / ((max - min) || 1) * 90;
  const toggleModel = (model: string) => setVisibleModels((current) => current.includes(model) ? current.filter((item) => item !== model) : [...current, model]);
  if (!query) return <div className="page-stack"><section className="panel compare-empty"><span className="eyebrow">MODEL TRADE-OFFS</span><h3>Select a dataset and query in Query Lab first.</h3><p>Model-level medians and quality comparisons appear after a query is selected.</p></section></div>;
  const insight = chart === "pareto" ? "Highlighted points are Pareto-efficient for this selected query: no other shown model is both better on quality and lower on energy." : chart === "co2" ? "Lower points on the CO2 comparison represent lower recorded emissions for this query." : chart === "latency-energy" ? "The chart makes the latency/energy trade-off visible; neither axis is treated as a universal winner." : chart === "accuracy-energy" ? "The quality axis follows this dataset's recorded contract, so accuracy is only compared within compatible records." : "Use the quality bars with the table to see the recorded quality/resource trade-off for this query.";
  return <div className="page-stack"><section className="section-title model-compare-intro"><span className="eyebrow">MODEL TRADE-OFFS</span><p>{dataset} · query-specific medians across ten cold-cache runs. {contract ? `${contract.label} is the recorded quality axis; ${contract.direction}.` : "This query has no comparable quality score in the archive."}</p></section><section className="panel compare-controls"><div className="chart-switcher"><span>Chart view</span><div role="tablist" aria-label="Model comparison charts">{modelChartOptions.map((option) => <button key={option.value} role="tab" aria-selected={chart === option.value} className={chart === option.value ? "active" : ""} onClick={() => setChart(option.value)}>{option.label}</button>)}</div></div><div className="model-toggles"><span>Models</span>{summary.map((item) => <label key={item.model}><input type="checkbox" checked={visibleModels.includes(item.model)} onChange={() => toggleModel(item.model)} />{modelLabel(item.model)}</label>)}</div></section><section className="panel comparison-table"><div className="table-head"><span>Model</span><span>{contract?.label ?? "Quality"}</span><span>Median runtime</span><span>Median energy</span><span>Median CO2</span><span>Status</span></div>{shown.map((item) => <div className="table-row" key={item.model}><strong><Sparkles size={15} /> <span>{modelLabel(item.model)}<small className="deployment">{item.deployment}</small></span></strong><span>{contract ? format(item.quality, 3) : "Not recorded"}{item.secondary !== null ? ` · ${item.secondaryLabel ?? "Secondary quality"} ${format(item.secondary, 3)}` : ""}</span><span>{format(item.runtime, 2, " s")}</span><span>{format(item.energy, 3, " Wh")}</span><span>{format(item.co2, 3, " g")}</span><small>{item.energy !== null && item.energy === lowEnergy ? "Lowest recorded energy" : "Recorded"}</small></div>)}</section>{chart === "quality" ? <section className="panel chart-panel"><div className="chart-heading"><div><span className="eyebrow">QUALITY COMPARISON</span><h3>{contract?.label ?? "Quality unavailable"}</h3></div><span>median across {source.length ? Math.max(...summary.map((item) => item.rows.length)) : 0} runs</span></div>{contract ? shown.map((item) => <div className="bar-row" key={item.model}><span>{modelLabel(item.model)}</span><div><i style={{ width: `${position(item.quality, minQuality, maxQuality, contract.direction === "lower is better")}%` }} /></div><strong>{format(item.quality, 3)}</strong></div>) : <p className="empty-state">No comparable quality metric is recorded for this query.</p>}</section> : <ModelPlot chart={chart} rows={shown} contract={contract} />}<p className="chart-insight">{insight}</p><p className="chart-note">Resource values are query-level medians. Local energy uses NVML measurement; online energy and CO2 use the archive&apos;s EcoLogits estimate. Pareto-efficient describes this selected query and metric pair only.</p></div>;
}
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyCompareQueries() {
  type QueryMetric = "quality" | "runtime" | "energy" | "co2" | "tokens" | "requests" | "cost";
  const stored = readCompareQueriesState();
  const [dataset, setDataset] = useState<string>(stored.dataset ?? "");
  const [model, setModel] = useState<string>(stored.model ?? "");
  const [metric, setMetric] = useState<QueryMetric>(!["runtime", "energy", "co2", "tokens"].includes(stored.metric) ? "energy" : stored.metric ?? "runtime");
  const [selectedQueries, setSelectedQueries] = useState<string[]>(stored.selectedQueries ?? []);
  useEffect(() => { localStorage.setItem(compareQueriesStorageKey, JSON.stringify({ dataset, model, metric, selectedQueries })); }, [dataset, model, metric, selectedQueries]);
  const datasets = [...new Set(records.map((record) => record.dataset))].sort();
  const queries = [...new Set(records.filter((record) => record.dataset === dataset).map((record) => record.query))].sort();
  const models = [...new Set(records.filter((record) => record.dataset === dataset).map((record) => record.model))].sort();
  const rows = selectedQueries.map((query) => {
    const source = records.filter((record) => record.dataset === dataset && record.query === query && record.model === model);
    const quality = median(source.map((record) => primaryQuality(record)?.value));
    const value = metric === "quality" ? quality : metric === "runtime" ? median(source.map((record) => record.runtime_seconds)) : metric === "energy" ? median(source.map((record) => record.energy_wh)) : metric === "co2" ? median(source.map((record) => record.co2_g)) : metric === "tokens" ? median(source.map((record) => typeof record.total_tokens === "number" ? record.total_tokens : null)) : metric === "requests" ? median(source.map((record) => (typeof record.planner_requests === "number" ? record.planner_requests : 0) + (typeof record.local_requests === "number" ? record.local_requests : 0))) : median(source.map((record) => typeof record.api_cost_usd === "number" ? record.api_cost_usd : null));
    const qualityLabels = [...new Set(source.map((record) => primaryQuality(record)?.label).filter(Boolean))];
    return { query, value, quality, qualityLabels, runs: source.length };
  });
  const values = rows.map((row) => row.value).filter((value): value is number => value !== null); const maximum = Math.max(...values, 1);
  const metricLabel = metric === "quality" ? "Quality metric" : ({ runtime: "Runtime", energy: "Energy", co2: "CO2", tokens: "Tokens", requests: "Requests", cost: "API cost" }[metric]);
  const metricUnit = metric === "runtime" ? " s" : metric === "energy" ? " Wh" : metric === "co2" ? " g" : metric === "cost" ? " USD" : "";
  const toggleQuery = (query: string) => setSelectedQueries((current) => current.includes(query) ? current.filter((item) => item !== query) : [...current, query]);
  return <div className="page-stack"><section className="section-title"><span className="eyebrow">QUERY TRADE-OFFS</span><h2>Compare query workloads</h2><p>Compare multiple queries under the same model. Quality values keep their recorded metric contract; resource values use ten-run medians.</p></section><section className="panel query-compare-controls"><label><span>Dataset</span><select value={dataset} onChange={(event) => { setDataset(event.target.value); setModel(""); setSelectedQueries([]); }}><option value="">Select a dataset</option>{datasets.map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Model</span><select value={model} onChange={(event) => setModel(event.target.value)} disabled={!dataset}><option value="">Select a model</option>{models.map((item) => <option key={item}>{modelLabel(item)}</option>)}</select></label><label><span>Metric</span><select value={metric} onChange={(event) => setMetric(event.target.value as QueryMetric)}><option value="quality">Quality</option><option value="runtime">Runtime</option><option value="energy">Energy</option><option value="co2">CO2</option><option value="tokens">Tokens</option><option value="requests">Requests</option><option value="cost">API cost</option></select></label><div className="query-checks"><span>Queries</span>{queries.map((item) => <label key={item}><input type="checkbox" checked={selectedQueries.includes(item)} onChange={() => toggleQuery(item)} />{queryLabel(item)}</label>)}</div></section>{!dataset || !model || !selectedQueries.length ? <section className="panel compare-empty"><span className="eyebrow">QUERY COMPARISON</span><h3>Select a dataset, model, and at least two queries.</h3></section> : <><section className="panel chart-panel"><div className="chart-heading"><div><span className="eyebrow">{metricLabel.toUpperCase()}</span><h3>{metricLabel}</h3></div><span>median across ten cold-cache runs</span></div>{rows.map((row) => <div className="bar-row" key={row.query}><span>{queryLabel(row.query)}</span><div><i style={{ width: `${((row.value ?? 0) / maximum) * 100}%` }} /></div><strong>{format(row.value, metric === "cost" ? 4 : 2, metricUnit)}</strong></div>)}</section><section className="panel query-compare-table"><div className="table-head"><span>Query</span><span>Recorded quality</span><span>Median runtime</span><span>Median energy</span><span>Median CO2</span><span>Runs</span></div>{rows.map((row) => <div className="table-row" key={row.query}><strong>{queryLabel(row.query)}</strong><span>{row.quality === null ? "Not recorded" : `${row.qualityLabels.join(" / ")}: ${format(row.quality, 3)}`}</span><span>{format(median(records.filter((record) => record.dataset === dataset && record.query === row.query && record.model === model).map((record) => record.runtime_seconds)), 2, " s")}</span><span>{format(median(records.filter((record) => record.dataset === dataset && record.query === row.query && record.model === model).map((record) => record.energy_wh)), 3, " Wh")}</span><span>{format(median(records.filter((record) => record.dataset === dataset && record.query === row.query && record.model === model).map((record) => record.co2_g)), 3, " g")}</span><small>{row.runs}</small></div>)}</section></>}</div>;
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyPhaseCompareQueries() {
  type QueryMetric = "quality" | "runtime" | "energy" | "co2" | "tokens" | "requests" | "cost";
  type QueryScope = "total" | "phase";
  const stored = readCompareQueriesState();
  const savedModel = records.find((record) => modelLabel(record.model) === stored.model)?.model ?? stored.model ?? "";
  const [dataset, setDataset] = useState<string>(stored.dataset ?? "");
  const [model, setModel] = useState<string>(savedModel);
  const [metric, setMetric] = useState<QueryMetric>(stored.metric ?? "runtime");
  const scope: QueryScope = "phase";
  const [selectedQueries, setSelectedQueries] = useState<string[]>(stored.selectedQueries ?? []);
  useEffect(() => { localStorage.setItem(compareQueriesStorageKey, JSON.stringify({ dataset, model, metric, selectedQueries })); }, [dataset, model, metric, selectedQueries]);
  const datasets = [...new Set(records.map((record) => record.dataset))].sort();
  const queries = [...new Set(records.filter((record) => record.dataset === dataset).map((record) => record.query))].sort();
  const models = [...new Set(records.filter((record) => record.dataset === dataset).map((record) => record.model))].sort();
  const number = (value: unknown) => typeof value === "number" && !Number.isNaN(value) ? value : null;
  const phaseTokens = (record: BenchmarkRecord, phase: "planner" | "execution") => { const input = number(record[`${phase}_input_tokens`]); const output = number(record[`${phase}_output_tokens`]); return input === null && output === null ? null : (input ?? 0) + (output ?? 0); };
  const rows = selectedQueries.map((query) => {
    const source = records.filter((record) => record.dataset === dataset && record.query === query && record.model === model);
    const quality = median(source.map((record) => primaryQuality(record)?.value));
    const total = metric === "quality" ? quality : metric === "runtime" ? median(source.map((record) => record.runtime_seconds)) : metric === "energy" ? median(source.map((record) => record.energy_wh)) : metric === "co2" ? median(source.map((record) => record.co2_g)) : metric === "tokens" ? median(source.map((record) => number(record.total_tokens))) : metric === "requests" ? median(source.map((record) => { const planner = number(record.planner_requests); const local = number(record.local_requests); const api = number(record.api_calls); return planner === null && local === null && api === null ? null : (planner ?? 0) + (local ?? 0) + (api ?? 0); })) : median(source.map((record) => number(record.api_cost_usd)));
    const phaseValue = (phase: "planner" | "execution") => metric === "runtime" ? median(source.map((record) => phase === "planner" ? record.planner_runtime_seconds : record.execution_runtime_seconds)) : metric === "energy" ? median(source.map((record) => phase === "planner" ? record.planner_energy_wh : record.execution_energy_wh)) : metric === "co2" ? median(source.map((record) => phase === "planner" ? record.planner_co2_g : record.execution_co2_g)) : metric === "tokens" ? median(source.map((record) => phaseTokens(record, phase))) : null;
    const qualityLabels = [...new Set(source.map((record) => primaryQuality(record)?.label).filter(Boolean))];
    return { query, total, planner: phaseValue("planner"), execution: phaseValue("execution"), quality, qualityLabels, runs: source.length };
  });
  const metricLabel = metric === "quality" ? "Quality metric" : ({ runtime: "Runtime", energy: "Energy", co2: "CO2", tokens: "Tokens", requests: "Requests", cost: "API cost" }[metric]);
  const metricUnit = metric === "runtime" ? " s" : metric === "energy" ? " Wh" : metric === "co2" ? " g" : metric === "cost" ? " USD" : "";
  const values = rows.flatMap((row) => scope === "phase" ? [row.planner, row.execution] : [row.total]).filter((value): value is number => value !== null);
  const maximum = Math.max(...values, 1);
  const toggleQuery = (query: string) => setSelectedQueries((current) => current.includes(query) ? current.filter((item) => item !== query) : [...current, query]);
  return <div className="page-stack"><section className="section-title"><span className="eyebrow">QUERY TRADE-OFFS</span><h2>Compare query workloads</h2><p>Compare selected queries under one model. The chart shows planner and execution consumption from the recorded runs.</p></section><section className="panel query-compare-controls"><label><span>Dataset</span><select value={dataset} onChange={(event) => { setDataset(event.target.value); setModel(""); setSelectedQueries([]); }}><option value="">Select a dataset</option>{datasets.map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Model</span><select value={model} onChange={(event) => setModel(event.target.value)} disabled={!dataset}><option value="">Select a model</option>{models.map((item) => <option key={item} value={item}>{modelLabel(item)}</option>)}</select></label><label><span>Metric</span><select value={metric} onChange={(event) => setMetric(event.target.value as QueryMetric)}><option value="quality" disabled>Quality</option><option value="runtime">Runtime</option><option value="energy">Energy</option><option value="co2">CO2</option><option value="tokens">Tokens</option><option value="requests" disabled>Requests</option><option value="cost" disabled>API cost</option></select></label><div className="query-checks"><span>Queries</span>{queries.map((item) => <label key={item}><input type="checkbox" checked={selectedQueries.includes(item)} onChange={() => toggleQuery(item)} />{queryLabel(item)}</label>)}</div></section>{!dataset || !model || selectedQueries.length < 2 ? <section className="panel compare-empty"><span className="eyebrow">QUERY COMPARISON</span><h3>Select a dataset, model, and at least two queries.</h3></section> : <><section className="panel chart-panel phase-chart-panel"><div className="chart-heading"><div><span className="eyebrow">PHASE COMPARISON</span><h3>Planner vs execution {metricLabel.toLowerCase()}</h3></div><span>median across {rows[0]?.runs ?? 0} runs per query</span></div>{rows.map((row) => <div className="phase-row" key={row.query}><strong>{queryLabel(row.query)}</strong><div className="phase-bars"><div><span>Planner</span><div className="phase-track"><i style={{ width: `${((row.planner ?? 0) / maximum) * 100}%` }} /></div><b>{format(row.planner, metric === "tokens" ? 0 : 3, metricUnit)}</b></div><div><span>Execution</span><div className="phase-track"><i style={{ width: `${((row.execution ?? 0) / maximum) * 100}%` }} /></div><b>{format(row.execution, metric === "tokens" ? 0 : 3, metricUnit)}</b></div></div></div>)}</section><section className="panel query-compare-table"><div className="table-head"><span>Query</span><span>Recorded quality</span><span>Planner</span><span>Execution</span><span>Total runtime</span><span>Total energy</span></div>{rows.map((row) => <div className="table-row" key={row.query}><strong>{queryLabel(row.query)}</strong><span>{row.quality === null ? "Not recorded" : `${row.qualityLabels.join(" / ")}: ${format(row.quality, 3)}`}</span><span>{format(row.planner, metric === "tokens" ? 0 : 3, metricUnit)}</span><span>{format(row.execution, metric === "tokens" ? 0 : 3, metricUnit)}</span><span>{format(median(records.filter((record) => record.dataset === dataset && record.query === row.query && record.model === model).map((record) => record.runtime_seconds)), 2, " s")}</span><span>{format(median(records.filter((record) => record.dataset === dataset && record.query === row.query && record.model === model).map((record) => record.energy_wh)), 3, " Wh")}</span></div>)}</section><p className="chart-note">Phase values are shown only when recorded. Local phase runtime may be unavailable; phase energy and CO2 may be estimates according to the archive provenance.</p></>}</div>;
}

type QueryCompareMetric = "quality" | "runtime" | "energy" | "co2" | "tokens" | "requests" | "cost";
const queryMetricUnit = (metric: QueryCompareMetric) => metric === "runtime" ? " s" : metric === "energy" ? " Wh" : metric === "co2" ? " g" : metric === "cost" ? " USD" : "";

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyOverallQueryChart({ rows, metric, unit }: { rows: Array<{ query: string; total: number | null; samples: number[] }>; metric: QueryCompareMetric; unit: string }) {
  const samples = rows.flatMap((row) => row.samples); const max = Math.max(...samples, 1); const x = (value: number) => 34 + (value / max) * 60;
  const quartiles = (values: number[]) => { const sorted = [...values].sort((a, b) => a - b); if (!sorted.length) return null; const q = (fraction: number) => sorted[Math.min(sorted.length - 1, Math.floor((sorted.length - 1) * fraction))]; return { min: sorted[0], q1: q(.25), median: q(.5), q3: q(.75), max: sorted.at(-1) ?? sorted[0] }; };
  return <section className="panel overall-query-chart"><div className="chart-heading"><div><span className="eyebrow">OVERALL QUERY COMPARISON</span><h3>Distribution of total {metric === "co2" ? "CO2" : metric}</h3></div><span>ten recorded runs per query</span></div><svg viewBox={`0 0 100 ${Math.max(150, rows.length * 54)}`} role="img" aria-label={`Overall ${metric} distribution comparison`} preserveAspectRatio="none"><line x1="34" y1="14" x2="94" y2="14" /><line x1="34" y1="14" x2="34" y2={rows.length * 54} />{rows.map((row, index) => { const box = quartiles(row.samples); const y = 38 + index * 54; if (!box) return <g key={row.query}><text x="4" y={y} className="box-label">{row.query.split("_")[0]}</text><text x="50" y={y} className="box-missing">Not recorded</text></g>; return <g key={row.query}><text x="4" y={y + 1} className="box-label">{row.query.split("_")[0]}</text><line x1={x(box.min)} y1={y} x2={x(box.max)} y2={y} className="box-whisker" /><line x1={x(box.min)} y1={y - 7} x2={x(box.min)} y2={y + 7} className="box-whisker" /><line x1={x(box.max)} y1={y - 7} x2={x(box.max)} y2={y + 7} className="box-whisker" /><rect x={x(box.q1)} y={y - 9} width={Math.max(1, x(box.q3) - x(box.q1))} height="18" className="box-range" /><line x1={x(box.median)} y1={y - 9} x2={x(box.median)} y2={y + 9} className="box-median" /><title>{`${queryLabel(row.query)}: median ${format(box.median, 2, unit)}`}</title></g>; })}</svg><div className="overall-chart-values">{rows.map((row) => <span key={row.query}><b>{queryLabel(row.query)}</b>{format(row.total, metric === "cost" ? 4 : 2, unit)} median</span>)}</div></section>;
}

function BetterOverallQueryChart({ rows, metric, unit }: { rows: Array<{ query: string; total: number | null; samples: number[] }>; metric: QueryCompareMetric; unit: string }) { const values = rows.flatMap((row) => row.samples); const rawMin = values.length ? Math.min(...values) : 0; const rawMax = values.length ? Math.max(...values) : 1; const padding = Math.max((rawMax - rawMin) * .12, rawMax * .02, .001); const domainMin = Math.max(0, rawMin - padding); const domainMax = rawMax + padding; const height = Math.max(220, rows.length * 80 + 65); const x = (value: number) => 184 + ((value - domainMin) / (domainMax - domainMin)) * 276; const quartiles = (samples: number[]) => { const sorted = [...samples].sort((a, b) => a - b); if (!sorted.length) return null; const q = (fraction: number) => sorted[Math.min(sorted.length - 1, Math.floor((sorted.length - 1) * fraction))]; return { min: sorted[0], q1: q(.25), median: q(.5), q3: q(.75), max: sorted.at(-1) ?? sorted[0] }; }; return <section className="panel overall-query-chart"><div className="chart-heading"><div><span className="eyebrow">OVERALL QUERY COMPARISON</span><h3>Recorded run spread</h3></div><span>recorded range; median, IQR, and min/max</span></div><svg viewBox={"0 0 480 " + height} role="img" aria-label={"Recorded " + metric + " run spread by query"} preserveAspectRatio="xMidYMid meet"><line x1="184" y1="20" x2="460" y2="20" className="distribution-axis" />{[0, .25, .5, .75, 1].map((tick) => <g key={tick}><line x1={184 + tick * 276} y1="20" x2={184 + tick * 276} y2={height - 35} className="distribution-grid" /><text x={184 + tick * 276} y={height - 17} textAnchor="middle" className="distribution-tick">{format(domainMin + tick * (domainMax - domainMin), metric === "tokens" ? 0 : 2, unit)}</text></g>)}{rows.map((row, index) => { const y = 60 + index * 80; const box = quartiles(row.samples); return <g key={row.query}><text x="176" y={y + 4} textAnchor="end" textLength="168" lengthAdjust="spacingAndGlyphs" className="distribution-label">{queryLabel(row.query)}</text>{box ? <><line x1={x(box.min)} y1={y} x2={x(box.max)} y2={y} className="distribution-whisker" /><line x1={x(box.min)} y1={y - 9} x2={x(box.min)} y2={y + 9} className="distribution-cap" /><line x1={x(box.max)} y1={y - 9} x2={x(box.max)} y2={y + 9} className="distribution-cap" /><rect x={x(box.q1)} y={y - 13} width={Math.max(3, x(box.q3) - x(box.q1))} height="26" rx="3" className="distribution-box" /><line x1={x(box.median)} y1={y - 13} x2={x(box.median)} y2={y + 13} className="distribution-median" /><title>{queryLabel(row.query) + ": range " + format(box.min, 3, unit) + " to " + format(box.max, 3, unit) + ", median " + format(box.median, 3, unit)}</title></> : <text x="190" y={y + 4} className="distribution-missing">Not recorded</text>}</g>; })}</svg><div className="overall-chart-values">{rows.map((row) => <span key={row.query}><b>{queryLabel(row.query)}</b><strong>{format(row.total, metric === "tokens" ? 0 : 2, unit)} median · n={row.samples.length}</strong></span>)}</div></section>; }

const operatorType = (operator: string) => /join/i.test(operator) ? "Join" : /aggregate|groupby/i.test(operator) ? "Aggregation" : /extractandqa/i.test(operator) ? "Model-backed extraction" : /(?:textqa|imageqa|audioqa).*filter/i.test(operator) ? "Model-backed filter" : /filter/i.test(operator) ? "Filter" : /project|rename|limit/i.test(operator) ? "Projection" : /qa|llm|model/i.test(operator) ? "Model-backed" : operator;
const complexityExplanation = (types: string[]) => { const modelBacked = types.some((type) => type.startsWith("Model-backed") || type === "Model-backed"); const filter = types.some((type) => type.includes("filter") || type === "Filter"); return types.includes("Join") ? "Joins combine relations before the remaining filters or model-backed work." : modelBacked && filter ? "Model-backed filtering evaluates each candidate with a model after the relational work." : types.includes("Aggregation") ? "Aggregation or grouping summarizes many input rows before the result is shaped." : modelBacked ? "Model-backed evaluation adds generation or media reasoning to the recorded flow." : filter ? "Filtering narrows candidate rows before projection or result shaping." : "The recorded flow is dominated by projection or result-shaping work."; };
const phaseShare = (value: number | null, planner: number | null, execution: number | null) => {
  if (value === null) return 0;
  const total = (planner ?? 0) + (execution ?? 0);
  return total > 0 ? Math.min(100, (value / total) * 100) : 0;
};

function donutPath(start: number, end: number, outer = 52, inner = 32) {
  const point = (radius: number, angle: number) => [60 + radius * Math.cos(angle), 60 + radius * Math.sin(angle)];
  const [outerStartX, outerStartY] = point(outer, start);
  const [outerEndX, outerEndY] = point(outer, end);
  const [innerEndX, innerEndY] = point(inner, end);
  const [innerStartX, innerStartY] = point(inner, start);
  const largeArc = end - start > Math.PI ? 1 : 0;
  return `M ${outerStartX} ${outerStartY} A ${outer} ${outer} 0 ${largeArc} 1 ${outerEndX} ${outerEndY} L ${innerEndX} ${innerEndY} A ${inner} ${inner} 0 ${largeArc} 0 ${innerStartX} ${innerStartY} Z`;
}

function PhaseDonut({ row, metric, unit }: { row: { query: string; planner: number | null; execution: number | null; total: number | null; runs: number }; metric: QueryCompareMetric; unit: string }) {
  const phaseTotal = (row.planner ?? 0) + (row.execution ?? 0);
  const hasPhase = phaseTotal > 0 && (row.planner !== null || row.execution !== null);
  const digits = metric === "tokens" ? 0 : 3;
  if (!hasPhase) return <div className="phase-donut-row"><div className="phase-donut-query"><strong>{queryLabel(row.query)}</strong><span>{row.runs} runs</span></div><span className="phase-unavailable">Phase values not recorded</span></div>;
  const plannerShare = phaseShare(row.planner, row.planner, row.execution) / 100;
  const start = -Math.PI / 2;
  const plannerEnd = start + plannerShare * Math.PI * 2;
  const executionEnd = start + Math.PI * 2;
  return <div className="phase-donut-row"><div className="phase-donut-query"><strong>{queryLabel(row.query)}</strong><span>{row.runs} runs</span></div><div className="phase-donut-visual"><svg viewBox="0 0 120 120" role="img" aria-label={`${queryLabel(row.query)} planner and execution phase share`}><path d={donutPath(start, plannerEnd)} className="phase-donut-planner" /><path d={donutPath(plannerEnd, executionEnd)} className="phase-donut-execution" /><text x="60" y="57" textAnchor="middle" className="phase-donut-total">{format(phaseTotal, digits, unit)}</text><text x="60" y="70" textAnchor="middle" className="phase-donut-caption">phase subtotal</text></svg><div className="phase-donut-legend"><span><i className="phase-dot planner" />Planner {Math.round(plannerShare * 100)}% · {format(row.planner, digits, unit)}</span><span><i className="phase-dot execution" />Execution {Math.round((1 - plannerShare) * 100)}% · {format(row.execution, digits, unit)}</span></div></div></div>;
}

function CompareQueries({ dataset, model, onDataset, onModel, metric, onMetric, selectedQueries, onSelectedQueries }: { dataset: string; model: string; onDataset: (value: string) => void; onModel: (value: string) => void; metric: QueryCompareMetric; onMetric: (value: QueryCompareMetric) => void; selectedQueries: string[]; onSelectedQueries: (value: string[]) => void }) {
  const setDataset = (value: string) => { onDataset(value); };
  const setModel = (value: string) => { onModel(value); };
  const datasets = [...new Set(records.map((record) => record.dataset))].sort();
  const queries = [...new Set(records.filter((record) => record.dataset === dataset).map((record) => record.query))].sort();
  const models = [...new Set(records.filter((record) => record.dataset === dataset).map((record) => record.model))].sort();
  const activeSelectedQueries = selectedQueries.filter((item) => queries.includes(item));
  const rows = activeSelectedQueries.map((query) => { const source = records.filter((record) => record.dataset === dataset && record.query === query && record.model === model); const value = (record: BenchmarkRecord) => metric === "runtime" ? record.runtime_seconds : metric === "energy" ? record.energy_wh : metric === "co2" ? record.co2_g : typeof record.total_tokens === "number" ? record.total_tokens : null; const total = median(source.map(value)); const phase = (name: "planner" | "execution") => metric === "runtime" ? median(source.map((record) => name === "planner" ? record.planner_runtime_seconds : record.execution_runtime_seconds)) : metric === "energy" ? median(source.map((record) => name === "planner" ? record.planner_energy_wh : record.execution_energy_wh)) : metric === "co2" ? median(source.map((record) => name === "planner" ? record.planner_co2_g : record.execution_co2_g)) : median(source.map((record) => { const input = record[`${name}_input_tokens`]; const output = record[`${name}_output_tokens`]; return typeof input !== "number" && typeof output !== "number" ? null : (typeof input === "number" ? input : 0) + (typeof output === "number" ? output : 0); })); const quality = source.length ? median(source.map((record) => primaryQuality(record)?.value)) : null; const operators = [...new Set(source.flatMap((record) => record.physical_operators ?? []))]; const types = [...new Set(operators.map(operatorType))]; return { query, total, samples: source.map(value).filter((item): item is number => item !== null), planner: phase("planner"), execution: phase("execution"), runs: source.length, quality, qualityLabel: source[0] ? primaryQuality(source[0])?.label ?? "Quality" : "Quality", runtime: median(source.map((record) => record.runtime_seconds)), energy: median(source.map((record) => record.energy_wh)), co2: median(source.map((record) => record.co2_g)), tokens: median(source.map((record) => typeof record.total_tokens === "number" ? record.total_tokens : null)), operators, types, structuredPlan: source.find((record) => record.execution_plan)?.execution_plan }; });
  const unit = queryMetricUnit(metric); const toggleQuery = (query: string) => onSelectedQueries(selectedQueries.includes(query) ? selectedQueries.filter((item) => item !== query) : [...selectedQueries, query]); const [inspectionQuery, setInspectionQuery] = useState<string | null>(null); const inspectionRecord = inspectionQuery ? records.filter((record) => record.dataset === dataset && record.model === model && record.query === inspectionQuery).sort((a, b) => a.run.localeCompare(b.run))[0] : undefined; useEffect(() => { if (!inspectionRecord) return; const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") setInspectionQuery(null); }; document.addEventListener("keydown", closeOnEscape); document.body.classList.add("modal-open"); return () => { document.removeEventListener("keydown", closeOnEscape); document.body.classList.remove("modal-open"); }; }, [inspectionRecord]);
  return <div className="page-stack"><section className="section-title"><span className="eyebrow">QUERY TRADE-OFFS</span><h2>Compare query workloads</h2><p>Compare selected queries under one model. Every total value is a median across that query/model&apos;s recorded runs; phase values are shown only when recorded.</p></section><section className="panel query-compare-controls"><label><span>Dataset</span><select value={dataset} onChange={(event) => { setDataset(event.target.value); setModel(""); onSelectedQueries([]); }}><option value="">Select a dataset</option>{datasets.map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Model</span><select value={model} onChange={(event) => setModel(event.target.value)} disabled={!dataset}><option value="">Select a model</option>{models.map((item) => <option key={item} value={item}>{modelLabel(item)}</option>)}</select></label><label><span>Metric</span><select value={metric} onChange={(event) => onMetric(event.target.value as QueryCompareMetric)}><option value="runtime">Runtime</option><option value="energy">Energy</option><option value="co2">CO2</option><option value="tokens">Tokens</option></select></label><div className="query-checks"><span>Queries</span>{queries.map((item) => <label key={item}><input type="checkbox" checked={selectedQueries.includes(item)} onChange={() => toggleQuery(item)} />{queryLabel(item)}</label>)}</div></section>{!dataset || !model || activeSelectedQueries.length < 2 ? <section className="panel compare-empty"><span className="eyebrow">QUERY COMPARISON</span><h3>Select a dataset, model, and at least two queries.</h3></section> : <><section className="panel query-plan-summaries"><div className="panel-heading"><div><span className="eyebrow">QUERY COMPLEXITY</span><h3>Recorded query summary</h3></div><span>selected query/model runs</span></div><div className="query-plan-summary-grid">{rows.map((row) => <article className="query-plan-summary" key={row.query}><div className="query-plan-summary-head"><strong>{queryLabel(row.query)}</strong><span>{row.runs} runs</span></div><div className="query-purpose"><span>Question</span><p>{queryText(row.query)}</p><small>{queryWorkload(row.query)}</small></div><div className="query-flow query-flow-legacy" title={row.operators.join(" → ")}><span className="flow-node flow-source">Data</span>{row.types.length ? row.types.map((type, index) => <span className="flow-step" key={`${row.query}-${type}-${index}`}><b aria-hidden="true">→</b><span className="flow-node">{type}</span></span>) : <span className="flow-step"><b aria-hidden="true">→</b><span className="flow-node">Not recorded</span></span>}<span className="flow-step"><b aria-hidden="true">→</b><span className="flow-node flow-result">Result</span></span></div><div className="query-plan-metrics"><span>Runtime <b>{format(row.runtime, 2, " s")}</b></span><span>Energy <b>{format(row.energy, 3, " Wh")}</b></span><span>CO2 <b>{format(row.co2, 3, " g")}</b></span></div><p className="complexity-note">{complexityExplanation(row.types)}</p><button className="plan-inspect-button" type="button" onClick={() => setInspectionQuery(row.query)}><FileCheck2 size={14} /> Inspect execution plan</button></article>)}</div></section><section className="query-chart-grid"><section className="panel chart-panel phase-chart-panel"><div className="chart-heading"><div><span className="eyebrow">PHASE SHARE</span><h3>Planner vs execution</h3></div><span>recorded phase medians</span></div><div className="phase-donut-grid">{rows.map((row) => <PhaseDonut row={row} metric={metric} unit={unit} key={row.query} />)}</div></section><BetterOverallQueryChart rows={rows} metric={metric} unit={unit} /></section><section className="panel query-compare-table"><div className="table-head"><span>Query</span><span>Recorded quality</span><span>Planner</span><span>Execution</span><span>Total runtime</span><span>Total energy</span><span>Total CO2</span><span>Total tokens</span><span>Runs</span></div>{rows.map((row) => <div className="table-row" key={row.query}><strong>{queryLabel(row.query)}</strong><span>{format(row.quality, 3)} {row.quality === null ? "" : row.qualityLabel}</span><span>{format(row.planner, metric === "tokens" ? 0 : 3, unit)}</span><span>{format(row.execution, metric === "tokens" ? 0 : 3, unit)}</span><span>{format(row.runtime, 2, " s")}</span><span>{format(row.energy, 3, " Wh")}</span><span>{format(row.co2, 3, " g")}</span><span>{format(row.tokens, 0)}</span><span>{row.runs || "Not recorded"}</span></div>)}</section><p className="chart-note">All values below are medians across the selected query/model&apos;s recorded runs. Donuts normalize only the recorded planner and execution phase subtotal; the distribution plot shows each recorded run. Missing phase fields remain Not recorded.</p></>}{inspectionRecord && <ComparePlanModal record={inspectionRecord} onClose={() => setInspectionQuery(null)} />}</div>;
}

function ComparePlanModal({ record, onClose }: { record: BenchmarkRecord; onClose: () => void }) {
  return <div className="plan-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
    <section className="plan-modal" role="dialog" aria-modal="true" aria-labelledby="compare-plan-title" onMouseDown={(event) => event.stopPropagation()}>
      <header className="plan-modal-header">
        <div><span className="eyebrow">EXECUTION PLAN</span><h2 id="compare-plan-title">{queryLabel(record.query)}</h2><p>{modelLabel(record.model)} · {record.run} · {record.deployment}</p></div>
        <button className="plan-modal-close" type="button" onClick={onClose}><X size={16} /> Cancel</button>
      </header>
      <div className="plan-modal-context"><strong>{queryText(record.query)}</strong><span>Inspecting one recorded run. Comparison values remain medians on the page behind this dialog.</span></div>
      <div className="plan-modal-body"><QueryPlan operators={record.physical_operators} query={record.query} executionPlan={record.execution_plan} record={record} /></div>
      <footer className="plan-modal-footer"><span>Full-query measurements are shown for the selected run; energy and latency are not allocated to individual operators.</span><button className="secondary-action" type="button" onClick={onClose}>Cancel</button></footer>
    </section>
  </div>;
}

function DatasetCompare() { const summary = [...new Set(records.map((record) => record.dataset))].map((dataset) => { const rows = records.filter((record) => record.dataset === dataset); const families = [...new Set(rows.map(qualityFamily))]; return { dataset, count: rows.length, queries: new Set(rows.map((record) => record.query)).size, models: new Set(rows.map((record) => record.model)).size, energy: median(rows.map((row) => row.energy_wh)), families, description: datasetDescription(dataset), workload: datasetWorkload(dataset), phase: rows.filter((row) => row.planner_energy_wh !== null && row.execution_energy_wh !== null).length, totals: rows.filter((row) => typeof row.runtime_seconds === "number" && typeof row.energy_wh === "number" && typeof row.co2_g === "number").length }; }); const max = Math.max(...summary.map((item) => item.energy ?? 0)); const phaseRecords = records.filter((record) => record.planner_energy_wh !== null && record.execution_energy_wh !== null).length; const phaseMissing = [...new Set(records.filter((record) => record.planner_energy_wh === null || record.execution_energy_wh === null).map((record) => record.dataset))]; const insights = [`Total runtime, energy, and CO2 are recorded for ${records.length}/${records.length} archive runs.`, `Planner/execution phase fields are recorded for ${phaseRecords}/${records.length} runs; ${phaseMissing.length ? `${phaseMissing.join(", ")} has no phase fields in the archive.` : "all datasets have phase fields."}`, "Throughput is unsupported because no source record contains a throughput field.", "Quality is reported by dataset-specific evaluation contract; the archive does not support one cross-dataset quality ranking."]; return <div className="page-stack"><section className="section-title"><span className="eyebrow">BENCHMARK COVERAGE</span><h2>Dataset comparison</h2><p>Compare dataset-level medians across all recorded query, model, and run observations. Quality contracts and phase coverage stay visible instead of being collapsed into one score.</p></section><section className="panel dataset-list">{summary.map((item) => <div className="dataset-row" key={item.dataset}><div><strong>{item.dataset}</strong><span>{item.description}</span><small>{item.workload}</small></div><div className="energy-bar"><i style={{ width: `${((item.energy ?? 0) / max) * 100}%` }} /></div><div><strong>{format(item.energy, 2, " Wh")}</strong><span>median total energy</span><small>{item.count} runs · {item.queries} queries · {item.models} models</small></div><div><span>{item.families.join(" · ")}</span><small>{item.totals}/{item.count} total metrics · {item.phase}/{item.count} phase records</small></div></div>)}</section><section className="panel audit-summary"><div className="panel-heading"><div><span className="eyebrow">DATA AUDIT</span><h3>What the archive can support</h3></div><span>{records.length} records checked</span></div>{insights.map((insight) => <p key={insight}>{insight}</p>)}</section></div>; }
function MeasurementRecords({ source, dataset, onDataset }: { source: BenchmarkRecord[]; dataset: string; onDataset: (value: string) => void }) { const rows = dataset ? source.filter((record) => record.dataset === dataset).slice(0, 30) : []; return <div className="page-stack"><section className="section-title evidence-heading"><div><span className="eyebrow">MEASURED RECORDS</span><h2>Measurement records</h2><p>Inspect the source measurements behind the aggregates shown in the console. These are individual recorded runs, not medians.</p></div><label className="inline-select"><span>Dataset</span><select value={dataset} onChange={(event) => onDataset(event.target.value)}><option value="">Select a dataset</option>{[...new Set(records.map((record) => record.dataset))].sort().map((item) => <option key={item}>{item}</option>)}</select></label></section>{!dataset ? <section className="panel empty-records-state"><span className="eyebrow">MEASURED RECORDS</span><h3>Select a dataset to inspect individual runs.</h3></section> : <section className="panel run-table"><div className="panel-heading"><div><span className="eyebrow">INDIVIDUAL RUNS</span><h3>{dataset} measurements</h3></div><span>Showing {rows.length} of {source.filter((record) => record.dataset === dataset).length} records</span></div><div className="table-head"><span>Query</span><span>Model</span><span>Run</span><span>Evaluation</span><span>Energy</span><span>Phase coverage</span></div>{rows.map((record) => <div className="table-row" key={`${record.query}-${record.model}-${record.run}`}><strong>{queryLabel(record.query)}</strong><span>{modelLabel(record.model)}</span><span>{record.run}</span><span>{qualitySummary(record)}</span><span>{format(record.energy_wh, 3, " Wh")}</span><small className={record.planner_energy_wh !== null && record.execution_energy_wh !== null ? "ok" : "pending"}>{record.planner_energy_wh !== null && record.execution_energy_wh !== null ? "Planner + execution" : "Total only"}</small></div>)}</section>}</div>; }
